CREATE TABLE BILL_LINE (LINE_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL, LINE_TYPE VARCHAR2(30) NOT NULL, SOURCE_REFERENCE VARCHAR2(160) NOT NULL, DESCRIPTION VARCHAR2(500) NOT NULL, AMOUNT NUMBER(19,4) NOT NULL, OCCURRED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_LINE_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID), CONSTRAINT UQ_BILL_LINE_SOURCE UNIQUE (BILL_ID, SOURCE_REFERENCE, LINE_TYPE));
